const f={AED:"د.إ",AUD:"A$",BRL:"R$",CAD:"C$",CHF:"CHF",CNY:"¥",CZK:"Kč",DKK:"kr",EUR:"€",GBP:"£",HKD:"HK$",HUF:"Ft",IDR:"Rp",ILS:"₪",INR:"₹",JPY:"¥",KRW:"₩",MXN:"Mex$",MYR:"RM",NOK:"kr",NZD:"NZ$",PHP:"₱",PLN:"zł",SAR:"﷼",SEK:"kr",SGD:"S$",THB:"฿",TRY:"₺",TWD:"NT$",USD:"$",VND:"₫",ZAR:"R"};function l(t,n){const r=n.toUpperCase(),o=u(r),e=c(r),i=$(t,e);return o?`${o}${i}`:`${i} ${n}`}function m(t,n){const r=n.toUpperCase(),o=u(r);return`${$(t,c(r))}${o}`}function S(t,n){return p(t,c(n))}function M(t,n){const r=t.replace(/,/g,"").trim(),o=Number(r);if(!Number.isFinite(o)||o<=0)return 0;const e=c(n);return Math.round(o*10**e)}function u(t){return f[t.toUpperCase()]||t}function c(t){return new Set(["BIF","CLP","DJF","GNF","ISK","JPY","KMF","KRW","PYG","RWF","UGX","VND","VUV","XAF","XOF","XPF"]).has(t.toUpperCase())?0:2}function $(t,n){if(n===0)return t.toLocaleString();const r=10**n,o=t<0?"-":"",e=Math.abs(t),i=Math.floor(e/r),s=e%r;if(s===0)return`${o}${i.toLocaleString()}`;const a=String(s).padStart(n,"0");return`${o}${i.toLocaleString()}.${a}`}function p(t,n){if(n===0)return String(t);const r=10**n,o=t<0?"-":"",e=Math.abs(t),i=Math.floor(e/r),s=e%r;if(s===0)return`${o}${i}`;const a=String(s).padStart(n,"0");return`${o}${i}.${a}`}export{l as a,S as b,c,m as f,u as g,M as p};
